import * as React from "react"

import { cn } from "@/lib/utils"

type ButtonGroupProps = React.ComponentProps<"div"> & {
  /** Names the set for a screen reader: "Share Halden". */
  "aria-label": string
  /**
   * parentheses: one pair holds the set, hairlines between. column: the actions stacked as a narrow
   * ragged column, a dash hung in the margin beside the one you point at. sentence: the actions
   * written as a list in running text, with commas and a conjunction between them.
   */
  variant?: "parentheses" | "column" | "sentence"
  /** The word before the last action in a sentence: "or", "and", or the page's own language. */
  conjunction?: string
}

/** One pair of parentheses holds a set of Buttons; hairlines stand between them. Its Buttons drop their own brackets. */
function ButtonGroup({ className, variant = "parentheses", conjunction = "or", children, ...props }: ButtonGroupProps) {
  if (variant === "sentence") {
    // ponytail: the separators are English list punctuation; `conjunction` covers the word, not the commas.
    const items = React.Children.toArray(children)
    const last = items.length - 1
    return (
      <span role="group" data-slot="button-group" data-variant={variant} className={cn("db-btn-group", className)} {...(props as React.ComponentProps<"span">)}>
        {items.map((item, i) => (
          <React.Fragment key={i}>
            {i > 0 ? (
              <span className="db-btn-group-sep" aria-hidden="true">
                {i < last ? ", " : `${last > 1 ? "," : ""} ${conjunction} `}
              </span>
            ) : null}
            {item}
          </React.Fragment>
        ))}
      </span>
    )
  }
  return (
    <div role="group" data-slot="button-group" data-variant={variant} className={cn("db-btn-group", className)} {...props}>
      {children}
    </div>
  )
}

export { ButtonGroup, type ButtonGroupProps }

@layer components {
  /* ── db-btn-group ── one pair of parentheses holds the set */
  .db-btn-group { display: inline-flex; align-items: baseline; flex-wrap: wrap; color: var(--db-ink); }
  .db-btn-group::before, .db-btn-group::after { font-weight: 200; font-size: 1.2em; line-height: 0; }
  .db-btn-group::before { content: "(" / ""; margin-inline-end: 0.1em; }
  .db-btn-group::after { content: ")" / ""; margin-inline-start: 0.1em; }
  /* The set has its own brackets, so its Buttons drop theirs (and any redraw) whatever variant they carry. */
  .db-btn-group > .db-btn[data-slot="button"] {
    padding: 0 0.6em 0.16em; animation: none;
    background: linear-gradient(currentColor, currentColor) no-repeat 100% 100% / 0% var(--db-hairline);
    background-origin: content-box; background-clip: content-box;
    transition: background-size var(--db-moderato) var(--db-exhale), background-position 0s;
  }
  .db-btn-group > .db-btn[data-slot="button"]::before,
  .db-btn-group > .db-btn[data-slot="button"]::after { content: none; }
  .db-btn-group > .db-btn[data-slot="button"] + .db-btn { border-inline-start: var(--db-hairline) solid var(--db-rule-strong); }
  .db-btn-group > .db-btn[data-slot="button"]:is(:hover, [data-force~="hover"]):not(:disabled) { background-position: 0 100%; background-size: 100% var(--db-hairline); animation: none; }
  /* Right to left, the line enters from the other side. */
  .db-btn-group:is([dir="rtl"], [dir="rtl"] *) > .db-btn[data-slot="button"] { background-position: 0 100%; }
  .db-btn-group:is([dir="rtl"], [dir="rtl"] *) > .db-btn[data-slot="button"]:is(:hover, [data-force~="hover"]):not(:disabled) { background-position: 100% 100%; }

  /* column: after "Less is more." and Healthy habits, the actions stacked as a narrow ragged column at tight leading, no rules between.
     Pointing hangs the poster's short heavy dash in the margin beside the action; it grows out from the word and goes back into it. */
  .db-btn-group[data-variant="column"] { display: inline-flex; flex-direction: column; align-items: flex-start; flex-wrap: nowrap; }
  .db-btn-group:is([data-variant="column"], [data-variant="sentence"])::before, .db-btn-group:is([data-variant="column"], [data-variant="sentence"])::after { content: none; }
  .db-btn-group[data-variant="column"] > .db-btn[data-slot="button"] { padding: 0.2em 0; line-height: 1.25; background: none; }
  .db-btn-group[data-variant="column"] > .db-btn[data-slot="button"] + .db-btn { border: 0; }
  .db-btn-group[data-variant="column"] > .db-btn[data-slot="button"]::before {
    content: ""; position: absolute; inset-inline: auto calc(100% + 0.5em); inset-block: calc(50% - 0.05em) auto; font-size: 1em; inline-size: 0.9em; block-size: max(var(--db-stroke), 0.15em);
    background: currentColor; scale: 0 1; transform-origin: 100% 50%; transition: scale var(--db-moderato) var(--db-exhale);
  }
  .db-btn-group[data-variant="column"]:is([dir="rtl"], [dir="rtl"] *) > .db-btn[data-slot="button"]::before { transform-origin: 0 50%; }
  .db-btn-group[data-variant="column"] > .db-btn[data-slot="button"]:is(:hover, :focus-visible, [data-force~="hover"]):not(:disabled)::before { scale: 1 1; }
  .db-btn-group[data-variant="column"] > .db-btn[data-slot="button"]:active:not(:disabled)::before { scale: 1.4 1; transition-duration: var(--db-allegro); }

  /* sentence: the actions written as a list in running text (copy the link, email it, or export a PDF), the way prose names choices.
     Each action stands on a pencil hairline; pointing passes an ink line through it, the group's own motion. The group takes the text's size. */
  .db-btn-group[data-variant="sentence"] { display: inline; color: inherit; }
  .db-btn-group[data-variant="sentence"] > .db-btn[data-slot="button"] {
    vertical-align: baseline; padding: 0 0 0.12em; font-size: inherit; line-height: inherit; letter-spacing: inherit; color: var(--db-ink);
    background:
      linear-gradient(currentColor, currentColor) no-repeat 100% 100% / 0% var(--db-hairline),
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / 100% var(--db-hairline);
    background-origin: border-box; background-clip: border-box;
  }
  .db-btn-group[data-variant="sentence"] > .db-btn[data-slot="button"]:is(:hover, [data-force~="hover"]):not(:disabled) { background-position: 0 100%, 0 100%; background-size: 100% var(--db-hairline), 100% var(--db-hairline); }
  .db-btn-group[data-variant="sentence"]:is([dir="rtl"], [dir="rtl"] *) > .db-btn[data-slot="button"] { background-position: 0 100%, 0 100%; }
  .db-btn-group[data-variant="sentence"]:is([dir="rtl"], [dir="rtl"] *) > .db-btn[data-slot="button"]:is(:hover, [data-force~="hover"]):not(:disabled) { background-position: 100% 100%, 0 100%; }
  .db-btn-group[data-variant="sentence"] > .db-btn[data-slot="button"]:disabled { background-image: none; }
  .db-btn-group-sep { white-space: pre-wrap; }

  @media (forced-colors: active) {
    .db-btn-group[data-variant="column"] > .db-btn[data-slot="button"]::before { forced-color-adjust: none; background: ButtonText; }
    .db-btn-group[data-variant="sentence"] > .db-btn[data-slot="button"] { text-decoration: underline; text-decoration-thickness: 1px; }
  }
}
